# -*- coding: utf-8 -*-
import json, os, sys
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from ai_trader.journal import Journal
L = json.loads(r'''["（这一条取代几分钟前那条同主题日志：那条用的是本地 13200 根库，少了近一年，数字偏低。","  两条都留着，因为「我发过一条错数字」这件事本身该留下痕迹。）","","这轮原本想去核对「回测和线上是不是同一套规则」。","结果是：不是。而且我事先猜错了方向。","","=== 一、发现 ===","","tools/liveedge.py 是产出「这个策略能赚多少」头条数字的工具。它的规则是：","","    进  if C[i] > s and C[i-1] <= sp        # s 是裸 SMA","    出  elif C[i] < s","","而线上 TrendStrategy 是带滞回的两条线：","","    进  cl[-1] >  sma*(1+h)","    出  cl[-1] <= sma*(1-h)","","也就是说：量「真实边际」的工具，量的不是线上那套规则的边际。","","=== 二、量化（服务器权威库：14999 根 4h，2019-12~2026-11，双边 0.10%）===","","    滞回带      总收益    CAGR     回撤    笔数   累计手续费","    0%（旧口径） +986%   +41.7%   47.8%   213    235.4%","    0.1%        +1151%  +44.7%   46.1%   172    207.7%","    0.2%（线上） +1175%  +45.1%   46.1%   147    178.1%","    0.5%        +1265%  +46.5%   44.3%   116    157.5%","    1%          +1423%  +48.9%   40.9%    84    135.3%","    2%          +1387%  +48.4%   43.1%    54     86.0%","","六年里累计手续费是权益的 235%（旧口径）。成本不是次要项，它是主要约束。","","=== 三、我猜错了方向 ===","","动手前我判断：滞回带让买点更晚更高、卖点更晚更低，对只做多应该有害。","所以我会预期 0.2% 比 0% 差。","","数据是反的：0.2% 比 0% 好 189 个百分点，笔数少 66 笔。","带子过滤掉擦边的假突破，省下的手续费是 57 个百分点的权益（235.4% -> 178.1%）。","","所以不是「线上比回测差」，而是「工具长期低估了策略」。","结论方向反了，但缺陷是真的：工具跑的确实不是线上规则。","","=== 四、数据源也要说清楚 ===","","我第一版是在本地库量的（13200 根，2020-10 起，少了将近一年），得出差 76 个百分点。","服务器上的库才是权威数据，本地那份是它的子集。以服务器为准：差 189 个百分点。","差点又拿一份残缺数据下结论。","","=== 五、修法：让它不可能再走散 ===","","1) 带子从真实配置导入（TradingCfg().trend_hysteresis_pct），工具里不许再写字面量。","2) 把循环抽成 simulate()，这样才可能做【行为级】对照。","3) tests/test_liveedge_parity.py：同一份收盘序列，","   一边只由 TrendStrategy.state() 驱动，一边由 liveedge.simulate() 驱动，","   进出发生在哪一根必须逐笔相同。","","=== 六、变异：8 条，两轮才全红 ===","","第一轮 8 条里有 2 条绿的：","  「进场 >= 而非 >」—— 随机浮点几乎不会恰好等于阈值，序列里没有相等样本","  「进场比上上根」—— 那份数据上两种取法结果相同","","这两个都是真盲区。补法是把边界【造出来】：","  - 前 201 根恒为 100，最后一根恰好放在进场线上 -> 测严格大于","  - 构造 上-下-上，钉住进场必须落在 i=203 -> 测比的是上一根","","补边界时我又错了一次：用 100*(1-h) 当出场线，","但那时 SMA 窗口已经把先前进场的高价算进去了，价格压根没落在线上，","缺陷照样漏过去。正确做法是先算窗口、得到真实出场线、再把价格精确放上去。","","最终 8 条全部变红。","","=== 七、一个冲突，本轮不翻案 ===","","表里 h=1% 既收益更高、回撤更低、笔数还少 63%，看起来比线上的 0.2% 更好。","但 HANDOFF 前面记着「宽滞回带（h>=1%）」是被否决过的。","","这是同一个样本上挑参数，属于样本内优化。","以前否决它大概率是因为跨子区间不稳定，不是这张全期表。","只凭一张全期表翻掉一个经过检验的决定，正是这个项目反复出事的那类错误。","所以：记下来，不翻案。下一步该做的是放到滚动子区间上比，并且解释机制。","","=== 八、验证 ===","","全量 475 条全绿（469 -> 475）。","","账户仍未到账（现货 USDT = 0）。"]''')
meta = json.loads(r'''{"round":94,"theme":"量真实边际的工具跑的不是线上规则：裸均线 vs 滞回带，权威口径差 189 个百分点","hypothesis_wrong":"我事先判断滞回带对只做多有害；数据相反：0.2% 比 0% 好 189pp","data_source_error":"第一版用本地 13200 根基数（少近一年），服务器才是权威 14999 根；差点拿残缺数据下结论","mechanism":"带子过滤擦边假突破，笔数 213->147，手续费 235.4% -> 178.1% 权益","authoritative_table":{"0%":"+986% CAGR 41.7% DD 47.8% 213笔","0.2%":"+1175% CAGR 45.1% DD 46.1% 147笔","1%":"+1423% CAGR 48.9% DD 40.9% 84笔"},"fix":["带子从 TradingCfg 导入","循环抽成 simulate()","tests/test_liveedge_parity.py 逐笔对照"],"mutation_rounds":"第一轮 8 条中 2 条绿（>= 与 C[i-2]），补边界样本后 8/8 红","self_inflicted":"用 100*(1-h) 当出场线，但 SMA 窗口已含进场高价，价格没落在线上，缺陷漏过","conflict_not_relitigated":"h=1% 全期表更好，但与既有否决决定冲突；属样本内优化，本轮不翻案，待滚动子区间验证","honest_risk_updated":{"total":"+1175%","CAGR":"+45.1%","MDD":"46.1%","Calmar":0.98,"trades":147,"in_market":"52%","MAE":"11.6%"},"tests_total":475,"account_state":{"spot_usdt":0}}''')
J = Journal('data/market_trade.db')
J.start()
J.add('info', u'量真实边际的工具跑的不是线上规则：裸均线 vs 滞回带',
      chr(10).join(L), json.dumps(meta, ensure_ascii=False))
print('journal ok')
J.stop()